using System.Net;using System.Net.Http;using System.Text.Json;using System.Text.Json.Nodes;using System.Reflection;using TownOfHost;using TownOfHost.Modules;
partial class Program{
static void WaitFetch()=>Check(SpinWait.SpinUntil(()=>(int)typeof(StreamerInfo).GetField("fetching",flags).GetValue(null)==0,15000),"fetch did not stop");
static void StartFetch(){TownOfHost.Main.ShowStreamComments.Value=true;typeof(StreamerInfo).GetField("nextAttemptAt",flags).SetValue(null,DateTime.MinValue);typeof(StreamerInfo).GetField("lastFetchAt",flags).SetValue(null,-999f);StreamerInfo.CommentFrameTick(.02f);WaitFetch();}
static void RunCommentFix(){
Test("realistic ytcfg and renderer bootstrap",()=>Check(StreamCommentParser.TryBootstrap(Html(),out var s,out var a,out var d)&&s.clientVersion=="test-version"&&a.Count==1&&d.Config&&d.Renderer));
Test("uppercase client-version fallback",()=>{var h=Html().Replace("\"INNERTUBE_CONTEXT\":{\"client\":{\"clientVersion\":\"test-version\",\"visitorData\":\"synthetic-visitor\"}}","\"INNERTUBE_CLIENT_VERSION\":\"upper-version\"");Check(StreamCommentParser.TryBootstrap(h,out var s,out _,out _)&&s.clientVersion=="upper-version");});
Test("global unrelated continuation cannot replace chat token",()=>{var h="<script>var unrelated={\"continuation\":\"wrong-token\"};</script>"+Html();Check(StreamCommentParser.TryBootstrap(h,out var s,out _,out _)&&s.continuation=="synthetic-next");});
Test("client version cannot inject HTTP headers",()=>Check(!StreamCommentParser.TryBootstrap(Html().Replace("test-version","version\\r\\nInjected: value"),out _,out _,out var d)&&!d.Version));
Test("window assignment format",()=>Check(StreamCommentParser.TryBootstrap(Html().Replace("var ytInitialData=","window[\"ytInitialData\"] = "),out _,out _,out _)));
Test("initial null assignment does not hide later data",()=>Check(StreamCommentParser.TryBootstrap("ytInitialData=null;"+Html(),out _,out _,out _)));
Test("missing config cannot claim connected",()=>Check(!StreamCommentParser.TryBootstrap("<html>HTTP 200 unsupported page</html>",out var s,out _,out var d)&&s==null&&!d.Config&&!d.Renderer));
Test("malformed nested action safely skipped",()=>{var a=Actions();a.Insert(0,JsonNode.Parse("{\"addChatItemAction\":{\"item\":\"bad\"}}"));Check(StreamCommentParser.ParseActions(a).Count==1);});
Test("emoji shortcuts represented",()=>{var a=Actions();a[0]["addChatItemAction"]["item"]["liveChatTextMessageRenderer"]["message"]["runs"]=JsonNode.Parse("[{\"emoji\":{\"shortcuts\":[\":smile:\"]}}]");Check(StreamCommentParser.ParseActions(a).Single().Text==":smile:");});
Test("text truncation keeps Unicode scalar",()=>{var t=new string('x',2047)+"😀";Check(StreamCommentParser.ParseActions(Actions(text:t)).Single().Text.EndsWith("😀"));});
Test("invalid channel is not truncated into someone else's vote ID",()=>Check(StreamCommentParser.ParseActions(Actions(channel:new string('x',129))).Single().Channel==""));
Test("server polling delay respected within bounds",()=>{var h=Html().Replace("\"timeoutMs\":3000","\"timeoutMs\":10000");Check(StreamCommentParser.TryBootstrap(h,out var s,out _,out _)&&s.PollDelayMilliseconds==10000);});
Test("negative poll hint cannot cause busy loop",()=>{var h=Html().Replace("\"timeoutMs\":3000","\"timeoutMs\":-1");Check(StreamCommentParser.TryBootstrap(h,out var s,out _,out _)&&s.PollDelayMilliseconds==3000);});
Test("request uses browser UA and popout URL",()=>{ResetStream();var(i,h)=FakeStream(Html());var c=(HttpClient)typeof(StreamerInfo).GetField("client",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(i);Check(c.DefaultRequestHeaders.UserAgent.ToString().Contains("Chrome/")&&!c.DefaultRequestHeaders.UserAgent.ToString().Contains("TOH-Shell-Stream"));i.FetchAsync().GetAwaiter().GetResult();Check(h.Paths[0].Contains("is_popout=1"));StreamerInfo.StopNetwork();});
Test("HTTP failure shows fixed error and backoff",()=>{ResetStream();var(i,h)=FakeStream("ignored response");h.ResponseStatus=HttpStatusCode.Forbidden;StartFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.HttpError&&FrameTextUnderTest.BuildText().Contains("再試行中"));for(int x=0;x<10;x++)StreamerInfo.CommentFrameTick(.02f);Check(h.Paths.Count==1);StreamerInfo.StopNetwork();});
Test("timeout is an error not silently ignored",()=>{ResetStream();var(i,h)=FakeStream();h.Timeout=true;StartFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.NetworkError&&StreamerInfo.HasConnectionError);StreamerInfo.StopNetwork();});
Test("200 without chat data visible as failure",()=>{ResetStream();FakeStream("<html>unsupported</html>");StartFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.InvalidPage&&FrameTextUnderTest.BuildText().Contains("チャット情報"));StreamerInfo.StopNetwork();});
Test("invalid poll response reboots instead of reusing expired token",()=>{ResetStream();var(i,h)=FakeStream(Html(),"{\"error\":{\"code\":400}}",Html());i.FetchAsync().GetAwaiter().GetResult();StartFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.InvalidResponse&&typeof(StreamerInfo).GetField("chatData",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(i)==null);StartFetch();Check(h.Paths.Count==3&&h.Paths[2].Contains("live_chat?is_popout=1")&&StreamerInfo.Status==StreamerInfo.ConnectionStatus.Waiting);StreamerInfo.StopNetwork();});
Test("valid empty live response is connected not failure",()=>{ResetStream();var(i,h)=FakeStream(Html(),Live(new JsonArray()));StartFetch();StartFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.Waiting&&!StreamerInfo.HasConnectionError);StreamerInfo.StopNetwork();});
Test("actual formatter shows received comment safely",()=>{ResetStream();var(i,h)=FakeStream();Queue(i,"msg","viewer","<b>日本語😀</b>");Drain();var text=FrameTextUnderTest.BuildText();Check(text.Contains("＜b＞日本語😀＜/b＞")&&!text.Contains("<b>日本語"));StreamerInfo.StopNetwork();});
Test("both host and nonhost drain and display",()=>{foreach(bool host in new[]{true,false}){ResetStream();AmongUsClient.Instance.AmHost=host;var(i,h)=FakeStream(Html(),Live(Actions(id:"live",text:"Visible")));i.FetchAsync().GetAwaiter().GetResult();i.FetchAsync().GetAwaiter().GetResult();Drain();Check(StreamerInfo.RecentComments.Any(x=>x.Text=="Visible")&&FrameTextUnderTest.BuildText().Contains("Visible"));StreamerInfo.StopNetwork();}});
Test("status revision updates independently of comments",()=>{ResetStream();int before=StreamerInfo.StatusVersion;FakeStream("<html>unsupported</html>");StartFetch();Check(StreamerInfo.StatusVersion>before&&StreamerInfo.RecentComments.Count==0);StreamerInfo.StopNetwork();});
Test("diagnostics never include secrets identifiers or comment body",()=>{ResetStream();var(i,h)=FakeStream(Html(),Live(Actions(id:"DO-NOT-LOG-ID",channel:"DO-NOT-LOG-CHANNEL",text:"DO-NOT-LOG-BODY")));StartFetch();StartFetch();Drain();Check(TownOfHost.Logger.Logs.Count>0);foreach(var msg in TownOfHost.Logger.Logs)foreach(var sensitive in new[]{"synthetic-key","synthetic-next","synthetic-visitor","test-version","DO-NOT-LOG-ID","DO-NOT-LOG-CHANNEL","DO-NOT-LOG-BODY","https://"})Check(!msg.Contains(sensitive));StreamerInfo.StopNetwork();});
Test("body download has a deadline after headers",()=>{ResetStream();var(i,h)=FakeStream();h.HangBody=true;StartFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.NetworkError);StreamerInfo.StopNetwork();});
Test("explicit stop suppresses cancellation error",()=>{ResetStream();var(i,h)=FakeStream();h.HangBody=true;TownOfHost.Main.ShowStreamComments.Value=true;StreamerInfo.CommentFrameTick(.02f);SpinWait.SpinUntil(()=>h.Paths.Count>0,1000);StreamerInfo.StopNetwork();WaitFetch();Check(StreamerInfo.Status==StreamerInfo.ConnectionStatus.Paused&&TownOfHost.Logger.Warnings.Count==0);});
}
class HangingContent:HttpContent{protected override bool TryComputeLength(out long n){n=0;return false;}protected override Task SerializeToStreamAsync(Stream s,TransportContext c)=>Task.CompletedTask;protected override Task<Stream> CreateContentReadStreamAsync()=>Task.FromResult<Stream>(new HangingStream());}
class HangingStream:Stream{public override bool CanRead=>true;public override bool CanSeek=>false;public override bool CanWrite=>false;public override long Length=>throw new NotSupportedException();public override long Position{get=>0;set=>throw new NotSupportedException();}public override void Flush(){}public override int Read(byte[] b,int o,int n)=>throw new NotSupportedException();public override async ValueTask<int> ReadAsync(Memory<byte> b,CancellationToken ct=default){await Task.Delay(Timeout.Infinite,ct);return 0;}public override long Seek(long o,SeekOrigin s)=>throw new NotSupportedException();public override void SetLength(long n)=>throw new NotSupportedException();public override void Write(byte[] b,int o,int n)=>throw new NotSupportedException();}
}
